SEÚNTES QUE SE ENCONTRABAN EN EL LUGAR, POSTERIORMENTE, EL PERSONAL DE ESPECIALES DE LA JEFATURA DE TRÁNSITO EPI SUR TOMO CONTACTÓ CON MÉDICO DE TURNO, DR. CARLOS TRUJILLO, QUIEN DIAGNOSTICÓ AL SR. NESTOR CHURQUI LEON\r\n\r\n• FRACTURA DE FÉMUR DERECHO \r\n• FRACTURA DE BRAZO DERECHO. \r\n\r\nTRAS SER INGRESADO A LA SALA DE EMERGENCIAS, EL PACIENTE FUE DERIVADO AL ÁREA DE QUIRÓFANO PARA PROCEDER CON LA INTERVENCIÓN QUIRÚRGICA CORRESPONDIENTE.\r\n\r\n• SITUACIÓN DEL CASO: EL PRESENTE CASO SE ENCUENTRA EN PROCESO DE INVESTIGACIÓN", "clasificacion_hecho": "CAIDA", "gps_latitud_longitud": "-17.472984, -66.124059", "categoria_de_licencia": "\"M\"", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "CALLE", "sub_clasificacion_hechos": "CAIDA DE MOTOCICLISTA", "comunidad_localidad_ninguno": "KARA KARA", "tipo_de_servicio_que_presta": "PARTICULAR", "18_a_30_mayores_herido_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "NESTOR JAIME CHURQUI LEON", "tipo_de_vehiculo_protagonista": "MOTOCICLETA", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL VIEDMAN", "todos_los_nombres_de_los_afectados_": "NESTOR JAIME CHURQUI LEON", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI SUR", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CALLE VILLA BELEN INMEDIACIONES KARA KARA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS LEVES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. MY. WILLIAM POVEDA ALARCON CEL.79333191", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no":