INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (38, '2025-08-03 12:30:00', -17.39212625, -66.15017414, NULL, 'TRANSITO EPI SUR', 'transito_03a', '048/2025', '{"edad": "SE DIO A LA FUGA", "sexo": "SE DIO A LA FUGA", "placa": "SE DIO A LA FUGA", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "048/2025", "gestion": 2025, "form03a_": 10, "provincia": "CERCADO", "cod_filtro": 1, "hora_hecho": "1899-12-30T13:02:36.000Z", "municipios": "COCHABAMBA", "soat_si_no": "SE DIO A LA FUGA", "zona_hecho": "SUR", "fecha_hecho": "2025-08-03T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 2, "total_muertos": 0, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "SE DIO A LA FUGA", "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "APREHENDIDO", "numero_de_licencia": "SE DIO A LA FUGA", "area_rural_o_urbano": "URBANO", "breve_detalle_hecho": "BREVE DETALLE DEL HECHO: En fecha 03 de agosto del 2025 a horas 11:30 a.m. aprox. Ingreso  a la oficina de Transito EPI SUR, la Sra. Felisa Rocha Aparicio la misma refiere haber sido victima de un hecho de Transito Técnicamente denominado CONDUCCION PELIGROSA CON PERSONAS HERIDAS Y FUGA DE PROTAGONISTA, en circunstancias que la Sra. Felisa y su hija Zulma Alanez observan al Sr. Teodomiro Alanes Quevedo, conduciendo un vehículo clase automóvil marca Toyota tipo sprinter de color plomo con placa de circulación “NO IDENTIFICADO”, quien se desplazaba con sentido de orientación de sur a norte, por causas que se investigan las mismas habrían pretendido detener la marcha del vehículo colocándose sobre la vía (y en frente del vehículo en movimiento), donde el conductor al realizar una maniobra de esquive habría ocasionado la caída de la Sra. Felisa Rocha Aparicio (esposa del protagonista) y arrastre de la Sra. Zulma Alanez Rocha (hija del conductor), a consecuencia del hecho de tránsito resultaron con lesiones personales (heridas visibles la Sra. Felisa Rocha Aparicio de 53 años de edad con CI. 8752385 en la región del pómulo derecho y la Sra. Soledad Zulma Alanes Rocha de 29 años de edad con CI. 8801767, con moretón en la mano derecha, así mismo la Sra. Felisa Rocha Aparicio manifiesta que la persona que conducía el vehículo involucrado en el hecho seria Teodomiro Alanes Quevedo su esposo y funcionario Público Policial con el grado de Sof. SUP. DAP.  En reserva activa.\r\nSe hace notar que las victimas en primera instancia se apersonaron a la Fuerza Especial de lucha contra la Violencia (FELCV EPI SUR) a realizar su respectiva denuncia siendo derivadas a esta oficina de Transito EPI SUR las mismas que solamente dieron a conocer el hecho de manera verbal negándose a formalizar la respectiva denuncia formal por lo que la suscrita investigadora procede a la apertura de caso de OFICIO", "clasificacion_hecho": "OTROS HECHOS DE TRANSITO", "gps_latitud_longitud": "-17.482237 – 66.161368", "categoria_de_licencia": "SE DIO A LA FUGA", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "CONDUCCION PELIGROSA", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "SE DIO A LA FUGA", "18_a_30_mayores_herido_mujer": 1, "46_a_59_mayores_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "TEODOMIRO ALANEZ QUEVEDO", "tipo_de_vehiculo_protagonista": "SE DIO A LA FUGA", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SE DIO A LA FUGA", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "CLINICA PARTICULAR", "todos_los_nombres_de_los_afectados_": "PERSONA HERIDA: FELISA ROCHA APARICIO,  2.- SOLEDAD ZULMA ALANES ROCHA", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI SUR", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. IMNOMINADA ZONA COBOL", "empresa_sindicato_o_institucion_al_que_pertenece": "SE DIO A LA FUGA", "otros_datos_vehiculos_y_conductores_damnificadas": "SE DESCONOCE EL PARADERO DEL  MOTORIZADO", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. 2DO DELIA GUZMAN ESCOBAR CEL: 67550665", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "SE DIO A LA FUGA", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:35.989584', '2026-02-11 05:26:35.989584');
