INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (40, '2025-08-03 23:20:00', -17.38613600, -66.09791500, NULL, 'TRANSITO SACABA', 'transito_03a', '069/2025', '{"edad": 21, "sexo": "MASCULINO", "placa": "1027-LDN", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "069/2025", "gestion": 2025, "form03a_": 12, "provincia": "CHAPARE", "cod_filtro": 1, "hora_hecho": "1899-12-30T23:52:36.000Z", "municipios": "SACABA", "soat_si_no": "SI", "zona_hecho": "ESTE", "fecha_hecho": "2025-08-03T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 2, "total_muertos": 0, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "heridos_pasajeros": 1, "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "ARRESTADO", "numero_de_licencia": 6428782, "area_rural_o_urbano": "RURAL", "breve_detalle_hecho": "BREVE DETALLE. -  A horas 19:25 p.m.  por instrucciones de la Central de Radio Patrullas 110 Sacaba, personal de la División Accidentes nos constituimos a la Av. Villazón  km. 5 altura rotonda Bella Vista a verificar un hecho de tránsito técnicamente denominado COLISION CON HERIDOS  que se habría suscitado a hrs: 19:20  p.m. aproximadamente. Protagonizado por la Motocicleta sin Placa de control, Marca Trueno, Color Gris Combinado,  conducido por el Sr. Jhonny Luna Antezana de 21 años de edad, con C.I. 12745788 licencia por verificar, el mismo que circulaba por la Av. Villazón en sentido de Oeste a Este por causas que se investigan llego a colisionar con la vagoneta con placa de circulación 2079-RZI Marca Toyota, Color Morado el mismo que realizaba una maniobra de viraje de Norte a Sud altura de la Rotonda Bella Vista,   a consecuencia del hecho resultaron heridos el conductor de la Motocicleta Sr. Jhonny Luna Antezana de 21 años y su acompañante Srta. Wendy Correa Mamani de 21 años. Los mismo que fueron auxiliados  inmediatamente por el conductor de la vagoneta al Hospital Salomón Klein con diagnostico  medico conductor de la motocicleta Sr. Jhonny policontusiones y su acompañante Srta. Wendy con diagnóstico Tec Grave,  los motorizados resultaron con  daños materiales de relativa consideración, ambos vehículos fueron traslados a la Posta de tránsito bajo inventario de rigor, el presente caso pasa  a conocimiento del Ministerio Público.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.386136, -66.097915", "categoria_de_licencia": "\"A\"", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION FRONTAL", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "18_a_30_mayores_herido_mujer": 1, "18_a_30_mayores_herido_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JHONNY LUNA ANTEZANA", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL SALOMON KLEIN", "todos_los_nombres_de_los_afectados_": "PERSONAS HERIDAS: JHONNY LUNA ANTEZANA 2-WENDY CORREA MAMANI", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO SACABA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. VILLAZON ALTURA ROTONDA BELLA VISTA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "TTE. BRANDON MONTAÑO ROJAS CEL: 69864586", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:36.22249', '2026-02-11 05:26:36.22249');
INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (41, '2025-08-04 09:20:00', -17.71009400, -66.67111900, NULL, 'TRANSITO QUILLACOLLO', 'transito_03a', '038/2025', '{"edad": 22, "sexo": "FEMENINO", "placa": "5581-SXP", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "038/2025", "gestion": 2025, "form03a_": 13, "provincia": "TAPACARI", "cod_filtro": 1, "hora_hecho": "1899-12-30T09:52:36.000Z", "municipios": "TAPACARI", "soat_si_no": "SI", "zona_hecho": "OESTE", "fecha_hecho": "2025-08-04T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 1, "total_muertos": 1, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "heridos_pasajeros": 1, "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "APREHENDIDO", "numero_de_licencia": 9205814, "area_rural_o_urbano": "RURAL", "breve_detalle_hecho": "BREVE DETALLE DEL HECHO:  A horas 06:00 aprox del día lunes, 04 de agosto de 2025, por instrucciones de Radio Patrullas 110, personal de accidentes Tránsito Quillacollo nos constituimos a inmediaciones de la  Localidad de Challa Grande, altura km. 109 carretera Cochabamba  - Oruro, provincia Tapacarí del Departamento de Cochabamba, a verificar un hecho de tránsito técnicamente denominado \"COLISIÓN POR INVASIÓN DE CARRIL CON PERSONA HERIDA Y FALLECIDA\" hecho que habria suscitado a horas 05:20 am. Aprox. donde automóvil, marca Suzuki, Tipo Alto, color blanco, con placa 5581-SXP, conducido por la Sta. LUCIA ANAHI ESCOBAR GALABURDA de 22 años de edad con licencia de conducir Nº 9205814 Cat. “P”, con sentido de circulación de Oeste a Este con dirección de occidente a Cochabamba por causas que se investiga invade parte del carril contrario llegando a colisionar con la parte anterior lado izquierdo a la parte anterior lado izquierdo del tracto Camión, marca Volvo, Tipo FH13, color azul, con placa 5351-CZN, conducido por el Sr. ABEL SILES MACIAS de 37 años de edad con licencia de conducir No. 8023063 Cat. Prof.  “C”, A cuya consecuencia del hecho resulto herido (la conductora del automóvil) quien esa  auxiliadlo y evacuado por ambulancia de centro de Salud Confital , posterior traslada al Hospital de Unival le  en internado con diagnostico medico FRACTURA FÉMUR IZQUIERDO, TEC LEVE Y POLITRAUMATISMO, en el lugar llega a fallecer el Sr. MATHIAS PAULO CANEDO de 19 años de edad con C.I. 14583229 con QR acompañante del automóvil en el lugar del hecho se realizó el acta de levantamiento legal de cadáver y se procedió a trasladar a dependencias del IDIF para la correspondiente autopsia de Ley. \r\nEl personal de la Caminera del retén CONFITAL me remite con acción directa en calidad de arrestados al conductor del Camión, Marca Volvo, color azul con placa 5351-CZN.\r\nNOMBRE DEL ARRESTADO   :  ABEL SILES MACIAS\r\nDOCUMENTO DE IDENTIDAD :      8023063 \r\nDOMICILIO       :  Calle Constantino Morales Final s/n, próximo Local Ayopaya Quillacollo.\r\nFECHA DE NACIMIENTO        : 02/11/1987\r\nLUGAR DE NACIMIENTO        : Quiri Quiri – Ayopaya - Cochabamba\r\nESTADO CIVIL:      : Soltero\r\nOCUPACIÓN:                            :       Chofer\r\n\r\nY a la conductora del vehiculo clase Automóvil, marca Suzuki, Tipo Alto, color blanco, con placa 5581-SXP.\r\n\r\nNOMBRE DEL ARRESTADO   :  LUCIA ANAHI ESCOBAR GALABURDA\r\nDOCUMENTO DE IDENTIDAD :      9205814 \r\nDOMICILIO       :  Calle Chipaya Nº 1334 Zona Sarcobamba.\r\nFECHA DE NACIMIENTO        : 15/05/2003\r\nLUGAR DE NACIMIENTO        : Cercado - Cochabamba\r\nESTADO CIVIL      : Soltero\r\nOCUPACIÓN                             :      Chofer\r\n           Asimismo, se procedió a la toma de muestra de sangre de los conductores: el Sr. ABEL SILES MACIAS y LUCIA ANAHI ESCOBAR GALABURDA para su respectivo procesamiento. Los vehículos protagonistas resultaron con daños materiales de consideración donde se procedió al trasladados a la posta autorizada, bajo inventario de rigor, el presente caso se encuentra en proceso de investigación pase a conocimiento de Ministerio Publico.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.710094, -66.671119", "categoria_de_licencia": "\"A\"", "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "COLISION FRONTAL", "heridos_cond_particulares": 1, "comunidad_localidad_ninguno": "CHALLA GRANDE", "tipo_de_servicio_que_presta": "PARTICULAR", "18_a_30_mayores_herido_mujer": 1, "18_a_30_mayores_muertos_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "LUCIA ANAHI ESCOBAR GALABURDA", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL UNIVAL", "todos_los_nombres_de_los_afectados_": "PERSONA HJERIDA: LUCIA ANAHI ESCOBAR GALABRUDA PERSONA FALLECIDA: MATJIAS PAULO CANEDO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "COCHABAMBA-ORURO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CARRETERA COCHABAMBA-ORUURO KM. 109 INMEDIACIONES LOCALIDAD CHALLA GRANDE", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. ALEXANDER OLIVERA ORELLANA CEL: 72244784", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "APREHENDIDO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-1