INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (42, '2025-08-04 14:00:00', -17.44365200, -66.16390500, NULL, 'TRANSITO EPI SUR', 'transito_03a', '018/2025', '{"edad": 37, "sexo": "MASCULINO", "placa": "1027-LDN", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "018/2025", "gestion": 2025, "form03a_": 14, "provincia": "CERCADO", "cod_filtro": 1, "hora_hecho": "1899-12-30T14:32:36.000Z", "municipios": "COCHABAMBA", "soat_si_no": "SI", "zona_hecho": "SUR", "fecha_hecho": "2025-08-04T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 0, "total_muertos": 0, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "NINGUNO", "numero_de_licencia": 6428782, "area_rural_o_urbano": "URBANO", "breve_detalle_hecho": "BREVE DETALLE DEL HECHO  Que en fecha 08 de Agosto del presente año, a promediar las 18:00 horas aproximadamente, personal de la División Especiales de la Jefatura de Tránsito EPI Sur a denuncia de transeúntes del lugar sobre un hecho de tránsito técnicamente DESPRENDIMIENTO DE LLANTA DELANTERA DERECHA SEGUIDO DE IMPACTO A VEHICULO ESTACIONADO  PILOTO TRASERO LATERAL DERECHO ocurrido en la Av. Panamericana Inmediaciones de la Estación Policial del Sur, Ante esto, el personal se constituyó en el lugar para verificar los hechos. Al llegar al lugar del hecho de tránsito, se tomó contacto con el Sr. Jhamil Calizaya Flores quien llega a referir que dejo su vehiculo estacionado sobre la Av. Panamericana, el cual se encontraba consumiendo alimento en la Panadería Pamelitas cuando llegaron oír un ruido donde al salir se llegar a percatar que un vehiculo tipo automóvil con placa de circulación 1027 – LDN se le llego a despender la llanta delantera derecha a lo cual llega a impactar contra su vehiculo el cual se encontraba estacionado a un costado de la via, motivo por el cual pusieron conocimiento a personal policial del hecho suscitado posteriormente se tomo contacto con el Sr. David Mollo Alconz conductor del vehiculo protagonista el mismo refiere que mientras conducía su vehiculo sobre la Av. Panamericana, llega a desprenderse su llanta delantera derecha el cual va impactar con un motorizado que se encontraba estacionado, motivo por el cual el vehiculo es conducido a a una posta autorizada. \r\n\r\nSITUACIÓN DEL CASO: El presente caso se encuentra en proceso de investigación", "clasificacion_hecho": "OTROS HECHOS DE TRANSITO", "gps_latitud_longitud": "-17.443652, -66.163905", "categoria_de_licencia": "\"A\"", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "SALIDA DE VIA POSTERIOR CHOQUE A OBJETO FIJO", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "DAVID MOLLO ALCONZ", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "NINGUNO", "todos_los_nombres_de_los_afectados_": "NINGUNO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 0, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI SUR", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. PANAMERICANA ALTURA ESTACION POLICIAL DEL SUR", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. MY. WILLIAM POVEDA ALARCON CEL.79333191", "situacion_jurica_del_s