o del Técnico Luis Enriquez Díaz Romero encargado  de U.G.R. de GOBERNACIÓN con:\r\n3 Efectivos de U.G.R., \r\n3 Efectivos de SAR- BOLIVIA\r\n2 Voluntarios de G.E.O. total 8 efectivos.\r\nEl Incendio vehicular aparentemente habria sido procovado por un corto circuito en el aire acondicionado, de los hechos No existen personas heridas, solo el siniestro del Omnibus.", "clasificacion_hecho": "OTROS HECHOS DE TRANSITO", "gps_latitud_longitud": "-17.853154, -65.446454", "categoria_de_licencia": "´´C´´", "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "INCENDIO DE VEHICULO", "comunidad_localidad_ninguno": "KINSA CHATA", "tipo_de_servicio_que_presta": "PUBLICO", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "ALCIDES VALLEJOS VILLARROEL", "tipo_de_vehiculo_protagonista": "OMNIBUS", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "NINGUNO", "todos_los_nombres_de_los_afectados_": "NINGUNO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "COCHABAMBA- SUCRE", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 0, "unidad_de_transito_que_registra_el_caso": "TRANSITO MIZQUE", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CARRETERA COCHABAMBA- SUCRE COMUNIDAD KINSA CHATTA", "empresa_sindicato_o_institucion_al_que_pertenece": "EMPRESA CARRASCO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES DE CONSIDERACION", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SBTTE. JOSUE CARRASCO FLORES CEL 67089685", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "ARRESTADO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:36.434188', '2026-02-11 05:26:36.43