r 11084080 cat. A quien circulaba de norte a sud, resultando del hecho de transito daños materiales de consideración en el automóvil por lo que se procedió al secuestro de ambos vehículos bajo inventario y trasladado a una posta autorizado por tránsito.\r\nSe procedió a la toma de muestra sanguínea para el examen de alcoholemia a ambos conductores por personal de laboratorio de la UMSS..\r\n\r\nEl presente caso se encuentra en proceso de investigación.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.392309, -66.208258", "categoria_de_licencia": "´´A´´", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION LATERAL", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "WILDER FLORES OTALORA", "tipo_de_vehiculo_protagonista": "CAMION", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "NINGUNO", "todos_los_nombres_de_los_afectados_": "NINGUNO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 0, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI COÑA COÑA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. BLANCO GALINDO / AV. SEXTA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. 1RO. ISRAEL CHAMBILLA CONDORI CEL. 68540198", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:36.538724', '2026-02-11 05