sionar en la parte lateral derecha de la patrulla llegado a causar daños materiales de relativa consideración, procediendo posteriormente a la colisión a descender de la patrulla para intervenir al infractor, momento en el cual el conductor trataba de encender nuevamente su vehiculo con la intención de darse a la fuga, procediendo a la aprehensión del conductor, que presentaba un fuerte aliento alcohólico y posteriormente es conducido a oficinas de la Jefatura de Tránsito de la EPI Sur para su correspondiente investigación. de igual manera ambos vehículos fueron trasladados a una posta policial autorizada. \r\n\r\n• SITUACIÓN DEL CASO: El presente caso se encuentra en proceso de investigación y pasa a conocimiento del Ministerio Publico.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.449260, -66.131520", "categoria_de_licencia": "\"C\"", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION LATERAL", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "31_a_45_mayores_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JUAN CARLOS ROJAS ZAMBRANA", "tipo_de_vehiculo_protagonista": "VAGONETA", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SANCIONABLE", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL DEL SUD", "todos_los_nombres_de_los_afectados_": "ALEJANDRA ULUNQUE REVOLLO 33 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI SUR", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. PETROLERA KM. 4 1/2 INMEDIACIONES DE LA UNIVERSIDAD DE SAN SIMON (FACULTAD DE AGRRONOMIA)", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_d