 tránsito no se registraron daños personales, pero si a daños materiales de consideración en el vehículo protagonista. Asimismo, personal de laboratorio de la U.M.S.S procedió a la toma de muestra de sangre para examen de alcoholemia al conductor.\r\nEl vehículo de acuerdo a procedimiento fue trasladado a posta autorizada bajo inventario de rigor. El presente caso se encuentra en proceso de investigación.", "clasificacion_hecho": "CHOQUE", "gps_latitud_longitud": "-17.392554, -66.199783", "categoria_de_licencia": "SIN LICENCIA", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "CHOQUE A OBJETO FIJO (ORNATO PUBLICO)", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JOSE RUDY LOAYZA CLAVEL", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "NINGUNO", "todos_los_nombres_de_los_afectados_": "NINGUNO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 0, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI COÑA COÑA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. BLANCO GALINDO ENTRE AV JUAN PABLO SEGUNDO", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SOF. SUP. DAP. ENRRIQUE CHOQUELA CRUZ CEL: 71447694", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:37.059033', '2026-02-11 0