A, con número de C.I. No. 972044 con 83 años de edad, que circulaba de Norte a Sud por la Av. segunda intersección  Av. Blanco Galindo, a  consecuente de este hecho de tránsito el Peatón, resultó con lesiones personales, siendo trasladado por las acompañantes del motociclista en un taxi, a la Caja Nacional de Salud av. Blanco Galindo Km. 5. Donde se encuentra en valoración médica, el presente caso se encuentra en proceso de investigación.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "-17.392793, -66.197122", "categoria_de_licencia": "SE DIO A LA FUGA", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "ATROPELO A PEATON", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "SE DIO A LA FUGA", "_60_adel_3_edad_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "SE DIO A LA FUGA", "tipo_de_vehiculo_protagonista": "MOTOCICLETA", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SE DIO A LA FUGA", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "CAJA NACIONAL DE SALUD", "todos_los_nombres_de_los_afectados_": "PERSONA HERIDA: FLORA FANOLA RIVERA DE 86 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI COÑA COÑA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. BLANCO GALINDO ENTRE AV SEGUNDA", "empresa_sindicato_o_institucion_al_que_pertenece": "SE DIO A LA FUGA", "otros_datos_vehiculos_y_conductores_damnificadas": "NINGUNO", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SOF. SUP. DAP. ENRRIQUE CHOQUELA CRUZ CEL: 71447694", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_p