on el Dr.  Antonine Fantine quien nos informa el deceso del señor David Wilfredo Villarroel Esteban, motivo por lo cual se evidencia a una persona de sexo masculino en una camilla metálica en posición decúbito dorsal sin signos vitales. procede a realizar el levantamiento legal del cadáver, para posterior trasladar al occiso a dependencias del IDIF para la autopsia de ley.\r\n    El presente caso se encuentra en proceso de investigación y pasa a conocimiento del Ministerio Publico.", "clasificacion_hecho": "CAIDA", "gps_latitud_longitud": "-17.780921, -65.932742", "categoria_de_licencia": "SIN LICENCIA", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "CALLE", "sub_clasificacion_hechos": "CAIDA DE MOTOCICLISTA", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "31_a_45_mayores_muertos_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "DAVID WILFREDO VILLARROEL ESTEBAN", "tipo_de_vehiculo_protagonista": "MOTOCICLETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL MUNICIPAL ANZALDO", "todos_los_nombres_de_los_afectados_": "FALLECIDO: DAVID WILFREDO VILLARROEL ESTEBAN", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO CLIZA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "C. ITALIA / C. SAN JOSE MUNICIPIO DE ANZALDO", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SOF. 2DO FERNANDO BUSTILLO VILLARRORL CEL. 68519543", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la