INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (64, '2025-08-11 12:30:00', -17.55536600, -65.83668600, NULL, 'TRANSITO PUNATA', 'transito_03a', '040/2025', '{"edad": 27, "sexo": "MASCULINO", "placa": "SIN PLACA", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "040/2025", "gestion": 2025, "form03a_": 36, "provincia": "PUNATA", "cod_filtro": 1, "hora_hecho": "1899-12-30T13:02:36.000Z", "municipios": "PUNATA", "soat_si_no": "NO", "zona_hecho": "SUR", "fecha_hecho": "2025-08-11T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 1, "total_muertos": 0, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "ARRESTADO", "numero_de_licencia": "SIN LICENCIA", "area_rural_o_urbano": "RURAL", "breve_detalle_hecho": "BREVE DETALLE HECHO: A horas 12:30 P.M. Aprox. del día lunes 11 de agosto de 2025 años, a llamado del Hospital Manuel Ascencio Villarroel de Punata, el cual refiere que se habría protagonizado un hecho de Tránsito a horas 08:30, por lo cual personal de tránsito Punata se hizo presente para la investigación correspondiente, el hecho de tránsito es   técnicamente denominado, “COLISION LATERAL CON HERIDO” hecho ocurrido en circunstancias en que la motocicleta, Marca: honda, Color: Blanco, sin placa de circulación, conducido por el Sr.  DIEGO FERNADES FELIPE de 27 años de edad, sin licencia de conducir, quien circulaba por la zona Villa Barrientos en sentido de circulación de este a oeste, por causas que se investiga llega a colisionar, con el vehículo marca Toyota, color Azul, con placa de control 2043-EPE quien fue impactado al lateral derecho, conducido por la Sr.  EDELFRIFO VALLEJOS VASQUEZ de 57 años con licencia de conducir 5922816 cat. “A”, quien c