cia del hecho de tránsito se tiene como resultado daños personales en la integridad física del conductor de la motocicleta quien es auxiliado y evacuado en ambulancia particular a la clínica Copacabana ingresando con diagnostico \r\npolicontuso y escoriaciones\r\nemitidito por el Dr. Ricardo Trigo Medico Traumatólogo posterior al diagnóstico y a los exámenes médicos el conductor de la motocicleta es dado de alta.\r\nAsí mismo los vehículos protagonistas fueron trasladados a dependencias de tránsito bajo inventario de rigor.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.373651, -66.144528", "categoria_de_licencia": "´´C´´", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION LATERAL", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "_60_adel_3_edad_herido_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "RICARDO CHUMACERO SANTOS", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "CLINICA COPACABANA", "todos_los_nombres_de_los_afectados_": "HERIDO: VICTOR MANUEL GANDARILLAS ILLANES", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO DIV. ACCIDENTES", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. AMERICA / C. BENJAMIN GUZMAN", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "Vehículo 2 clase: motocicleta, marca: Zeus, color: rojo, con placa de circulación nro. 5821-KHI", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. CRISTIAN ROJAS JOVE CEL. 6