INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (71, '2025-08-13 15:00:00', -17.39110135, -66.14461194, NULL, 'TRANSITO SACABA', 'transito_03a', '081/2025', '{"edad": 49, "sexo": "MASCULINO", "placa": "076-FUG", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "081/2025", "gestion": 2025, "form03a_": 43, "provincia": "CHAPARE", "cod_filtro": 1, "hora_hecho": "1899-12-30T15:32:36.000Z", "municipios": "SACABA", "soat_si_no": "NO", "zona_hecho": "ESTE", "fecha_hecho": "2025-08-13T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 0, "total_muertos": 1, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "APREHENDIDO", "numero_de_licencia": 4440852, "area_rural_o_urbano": "URBANO", "breve_detalle_hecho": "BREVE DETALLE HECHO:  \r\nEn fecha 13 de agosto de 2025, a Hrs 11:00 a.m. Aprox., ha llamado del despachador de 110 sacaba, personal de la División Accidentes de Tránsito, nos constituimos a una calle innominada zona el abra, a objeto de verificar un hecho de tránsito técnicamente denominado \" ATROPELLO SEGUIDO DE MUERTE DE PERSONA – (MENOR DE EDAD, en el lugar se tomó contacto con el Sr. JUAN REDY MENECES VARGAS (conductor del camión) de 49 años de edad, mismo refiere que en compañía del menor  JHOAN PEREIRA CARDOZO de 15 años, se encontraban en horario de trabajo repartiendo agua en la zona del abra, mismo se encontraba circulando con su vehículo, Clase CAMION, Marca ISUZU, color AZUL, con placa de circulación No. 076 - FUG servicio particular, mismo circulaba con sentido de orientación de Oeste a Este, por causas que se investiga llega a atropellar al Peatón identificado JHOAN PEREIRA CARDOZO de 15 años de edad, mismo según versión de testigos refieren que el peatón estaria encima del cilindro del camión y por casas que se investiga  habría caído y es atropellado, a consecuencia de este hecho de tránsito el peatón fallece instantáneamente en el lugar del hecho, mismo se encontraba de cubito ventral sobre la vía, posteriormente se realiza el levantamiento legal de cadáver, y es trasladado a la morgue de la IDIF. Para su respectiva autopsia de Ley.\r\nAsi mismo se procedió a la toma de muestra de humor vitreo por parte de personal de Laboratorio BIOLAB. al menor JHOAN PEREIRA CARDOZO de 15 años (fallecido) y muestra de sangre al Sr.  JUAN REDY MENECES VARGAS (conductor del camión) posterior se procedió al secuestro del camión, bajo inventario de rigor y posterior traslado a posta autorizada por tránsito, el presente caso se encuentra en proceso de investigación y pasa a conocimiento del ministerio Publico.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "- 17.423459, -66.084761", "categoria_de_licencia": "´´C´´", "clasificacion_de_la_via_": "CALLE", "sub_clasificacion_hechos": "ATROPELO A PEATON", "comunidad_localidad_ninguno": "EL ABRA", "tipo_de_servicio_que_presta": "PARTICULAR", "13_a_17_menores_muertos_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JUAN REDY MENECES VARGAS", "tipo_de_vehiculo_protagonista": "CAMION", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "IDIF", "todos_los_nombres_de_los_afectados_": "FALLECIDO: JHOAN PEREIRA CARDOZO 15 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO SACABA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CALLE INNOMINADA ZONA EL ABRA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "Vehículo, Clase CAMION, Marca ISUZU, color AZUL, con placa de circulación No. 076 - FUG servicio particular", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. DENNYS FACCIO CARRASCO CEL: 71495055", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "APREHENDIDO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:38.123515', '2026-02-11 05:26:38.123515');
