 los vehículos presentan daños materiales, seguidamente los vehículos fueron trasladados a dependencia de tránsito así también se procedió a la extracción de la Muestra Sanguínea de los conductores de los vehículos protagonista el presente caso se encuentra en proceso de investigación.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.395692,-66.307807", "categoria_de_licencia": "´´C´´", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION POR ALCANCE", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PUBLICO", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "LUIS REYNALDO CALLE BAUTISTA", "tipo_de_vehiculo_protagonista": "TRACTO CAMION", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "NINGUNO", "todos_los_nombres_de_los_afectados_": "NINGUNO", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 0, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. ALBINA APTIÑO / C. LITORAL", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. JAIME VILLCA CALANI CEL. 68838623", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:38.171968', '2026-02-11 05:26:38.171968');
