o. 5775842 Cat. A, sobrio acompañado de la Sra. Julia Roxana  Montoya Vera de 49 años de edad, quienes se  dirigían a la ciudad de Cochabamba, a cuya consecuencia resultaron  heridos, siendo  que  ambos se  constituyeron por su cuenta al Hospital  Jucheri de Colcapirhua (haciéndonos conocer al respecto a horas 09:00) indicándonos  que se  encuentran estables con lesiones  leves (policontuciones), y el vehículo presenta  daños  materiales  de  consideración; en cuanto  al  vehículo  protagonista después del hecho  de transito se  dio a la  fuga con  rumbo desconocido. El presente caso se encuentra en proceso de investigación.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.709023, -66.638917", "categoria_de_licencia": "SE DIO A LA FIGA", "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "COLISION FRONTAL", "heridos_cond_profesionales": 1, "comunidad_localidad_ninguno": "CHALLA GRANDE", "tipo_de_servicio_que_presta": "SE DIO A LA FUGA", "31_a_45_mayores_herido_varon": 1, "46_a_59_mayores_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "SE DIO A LA FUGA", "tipo_de_vehiculo_protagonista": "SE DIO A LA FUGA", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SE DIO A LA FIGA", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL JUCHERI", "todos_los_nombres_de_los_afectados_": "HERIDOS: EDUARDO MONTOYA VERA 34 AÑOS, JULIA ROXANA MONTOYA VERA 49 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "COCHABAMBA-ORURO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CARRETERA COCHABAMBA - ORURO KM. 97 ALTURA CHALLA GRANDE", "empresa_sindicato_o_institucion_al_que_pertenece": "SE DIO A LA FUGA", "ot