INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (83, '2025-08-16 21:45:00', -17.00707100, -65.10074800, NULL, 'TRANSITO CHIMORE', 'transito_03a', '032/2025', '{"edad": 35, "sexo": "MASCULINO", "placa": "3320-NBG", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "032/2025", "gestion": 2025, "form03a_": 55, "provincia": "CARRASCO", "cod_filtro": 1, "hora_hecho": "1899-12-30T22:17:36.000Z", "municipios": "CHIMORE", "soat_si_no": "NO", "zona_hecho": "ESTE", "fecha_hecho": "2025-08-16T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 0, "total_muertos": 1, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "00.00-00.00 GRADOS", "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "NINGUNO", "numero_de_licencia": 8728360, "area_rural_o_urbano": "RURAL", "breve_detalle_hecho": "BREVE DETALLE HECHO: El día Domingo 17 de Agosto del 2.025, a horas 06:45 a.m. Aprox., ha llamado via celular del personal médico de turno del Centro de Salud “San Juan de Dios de Chimore, quienes refieren que habría fallecido una persona herida por un hecho de tránsito, inmediatamente personal de turno de la Div. de Acc. De Transito se constituyó a dicho nosocomio y constituyéndonos al lugar a objeto de verificar el hecho, siendo fecha y hora del hecho en día sábado 16 de agosto del 2.025, a horas 17:45 p.m. Aprox., donde se registró un hecho de tránsito, técnicamente denominado “ENCUNETAMIENTO SEGUIDO DE CHOQUE A OBJETO FIJO CON HERIDO SEGUIDO DE MUERTE DE PERSONA”, en circunstancias en que el Vehículo Clase Motocicleta, con Placa 3320-NBG,  de servicio público perteneciente al Sind. de Moto taxis “2 de Junio”, Marca Kanda, Tipo KL 150-11, Modelo 2013, Color Rojo, sin SOAT, conducido por el Sr. HUGO MAIDANA MERINO de 35 años de edad, con Licencia de conducir Nro. 8728360 Cat. “M” Vigente, sin casco de protección, quien se encontraba circulando por el Camino Vecinal de Sindicato 5 de febrero a Población Valle Hermoso, con sentido de orientación de Sud a Norte, procedente desde Sind. Cabrera con destino a  la población de Valle Hermoso, al llegar a la altura del Sind. Valle Hermoso del Municipio de Chimore, por causas que se investiga, perdió el control de su motorizado y llego a encunetarse hacia su lado Izquierdo de la via y consecuentemente llegar a Chocar con la parte anterior frontal contra un objeto fijo (árbol de pacay).  A consecuencia de este hecho resulto herido el Sr. HUGO MAIDANA MERINO (conductor de la motocicleta) quien fue auxiliado por sus familiares en un vehículo particular hasta el Centro de Salud “San Juan de Dios”, donde recibió la atención médica en sala de emergencia y fue valorado con diagnóstico de (TEC MODERADO, LESION A NIVEL DE CRANEO, TRAUMA ABDOMINAL) de acuerdo al informe preliminar de la Dra. Vanesa Soldado Medico de Turno. Seguidamente a solicitud de la Sra. Isaura Quinteros Orellana (esposa del motociclista) solicito su alta voluntaria. Posteriormente en fecha domingo 17 de agosto del presente año, a horas 01:30 a.m. nuevamente fue auxiliado por sus familiares al mismo nosocomio de chimore solicitando atención medica por el fuerte dolor abdominal, seguidamente a horas 04:45 a.m. por la gravedad de sus lesiones en el abdomen el Sr. Hugo Maidana Merino (conductor de la motocicleta) fue evacuado en ambulancia al Hospital de “Villa Tunari III Nivel” de Paractito, en el trayecto antes de llegar al mencionado nosocomio de de Paractito – Villa Tunari llego a fallecer el Sr. Hugo Maidana Merino, posteriormente fue trasladado en la misma ambulancia y depositado en la morgue del Centro de Salud “San Juan de Dios” de Chimore para su correspondiente Autopsia de Ley. No se procedió a la extracción de toma de muestra sanguínea o humor vitreo para el análisis de laboratorio. El motorizado presenta daños materiales de relativa consideración y fue trasladado a la Posta particular “Chávez” bajo acta e inventario de rigor. El presente caso causas y circunstancias se encuentran en proceso de investigación. Y pasa a conocimiento del Ministerio Publico", "clasificacion_hecho": "ENCUNETAMIENTO", "gps_latitud_longitud": "-17.0070710, -65.1007480", "categoria_de_licencia": "M", "muertos_motociclistas": 1, "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "ENCUNETAMIENTO DE MOTOCICLETA", "comunidad_localidad_ninguno": "VALLE HERMOSO", "tipo_de_servicio_que_presta": "PUBLICO", "31_a_45_mayores_muertos_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "HUGO MAIDANA MERINO", "tipo_de_vehiculo_protagonista": "MOTOCICLETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "CENTRO DE SALUD SAN JUAN DE DIOS", "todos_los_nombres_de_los_afectados_": "FALLECIDO: HUGO MAIDANA MERINO 35 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO CHIMORE", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CAMINO VECINAL 5 DE FEBRERO POBLACION VALLE HERMOSO MUNICIPIO DE CHIMORE", "empresa_sindicato_o_institucion_al_que_pertenece": "SINIDICATO DE MOTO TAXIS 2 DE JUNIO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES DE CONSIDERACION", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. MY. JUAN LEDEZMA NOGALES CEL. 68580359", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:38.795751', '2026-02-11 05:26:38.795751');
