 a causa del hecho de transito resultó herido y fue evacuado a la Clinica Álvarez con diagnóstico de TEC LEVE, TRAUMA FACIAL, POLICONTUSION por el Dr. Rodrigo Rocha, medico de turno\r\n\r\nEl presente caso se encuentra en proceso de investigación y pasa a conocimiento del ministerio público.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.393364, -66.274313", "categoria_de_licencia": "C", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "COLISION POR ALCANCE", "0_a_12_niosas_herido_varon": 1, "comunidad_localidad_ninguno": "NINGUNA", "tipo_de_servicio_que_presta": "PARTICULAR", "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JOSE FERNANDO GARCIA FUENTES", "tipo_de_vehiculo_protagonista": "TRACTO CAMION", "division_accidentes_y_especiales": "ESPECIALES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "CLINICA ALVAREZ", "todos_los_nombres_de_los_afectados_": "HERIDO: MENOR URIEL THIAGO ARIAS ANTAKAHUA 3 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. ALVINA PATIÑO / C. LITORAL", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "Vehiculo 2. clase Motocicleta, marca Kanda, color rojo,con placa de circulacion 3909ICP", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. MY. FLAVIO MONTAÑO TORRICO CEL. 60360450", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:38.933938', '2026-02-11 05: