imismo se procede al levantamiento legal del cadáver y posterior traslado al IDIF, donde se encuentra a la espera de su autopsia médico legal .\r\nEl vehículo protagonista fue trasladado a posta de tránsito autorizado bajo inventario de rigor. El presente caso se encuentra en proceso de investigación y pasa a conocimiento del Ministerio Publico.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "-17.401473, -66.151350", "categoria_de_licencia": "´´C´´", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "ATROPELO A PEATON", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PUBLICO", "_60_adel_3_edad_muertos_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "RICHARD HERBAS PINAYA", "tipo_de_vehiculo_protagonista": "MICRO", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "IDIF", "todos_los_nombres_de_los_afectados_": "FALLECIDA: PERSONA DE SEXO FEMENINO NO IDENTIFICADA DE 65 A 70 AÑOS APROXIMADAMENTE", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO DIV. ACCIDENTES", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. REPUBLICA / C. HONDURAS", "empresa_sindicato_o_institucion_al_que_pertenece": "MICRO LL", "otros_datos_vehiculos_y_conductores_damnificadas": "NINGUNO", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "SGTO. MY. FERNANDO F. CAYOJA LOZA CEL. 67451001", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "APREHENDIDO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:39.541863', '2026-02-11 05:26: