idad  NO IDENTIFICADA, edad, 65 A 70 AÑOS aprox", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. DIEGO TROCOSO QUIROZ CEL. 63202208", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "APREHENDIDO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:40.151771', '2026-02-11 05:26:40.151771');
