parente estado de ebriedad, los cuales fueron trasladados al Hospital San Francisco de Asís para su atención médica, en tanto que el cuerpo del fallecido fue remitido a la morgue del mismo nosocomio para la autopsia de ley. El vehículo automóvil presentó daños materiales de consideración en la parte anterior, mientras que la volqueta no registró daños ni personas lesionadas. El presente caso, con sus causas y circunstancias, se encuentra en investigación y fue puesto a conocimiento del Ministerio Público.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-16.946738, -65.400316", "categoria_de_licencia": "´´C´´", "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "COLISION POR ALCANCE", "muertos_cond_profesionales": 1, "comunidad_localidad_ninguno": "SANTA ELENA", "tipo_de_servicio_que_presta": "PARTICULAR", "31_a_45_mayores_herido_varon": 1, "31_a_45_mayores_muertos_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "MOISES MERIDA QUISPE", "tipo_de_vehiculo_protagonista": "VOLQUETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SANCIONABLE", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL SAN  FRANCISCO DE ASIS", "todos_los_nombres_de_los_afectados_": "PERSONA FALLECIDA: EVER ARCE HINOJOSA DE 36 AÑOS - PERSONA HERIDA: AYDE ARGOTE DE 33 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO VILLA TUNARI", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "CARRETERA INTERPROVINCIAL VILLA TUNARI KM 4 ZONA SANTA ELENA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "vehículo clase volqueta, marca Volvo, color blanco, placa 2591-NES, de servi