ya y referido al hospital Manuel Ascencio Villarroel de Punata, seguidamente referido al hospital Viedma e internado con Diagnostico medico TRAUMA DE PIE POR ATRICION Y DEABETES DESCONTROLADA, a la espera del diagnóstico final.  \r\n\r\nSeguidamente se procedió a la toma de muestra sanguínea al conductor de la Vagoneta, para examen de alcoholemia por parte de Laboratorio BIOLAB, también se procedió al secuestro del motorizado y trasladado a la posta vehicular autorizado por tránsito, el presente caso se encuentra en proceso de investigación y pasa a conocimiento del ministerio público.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "-17.514013, -65.856679", "categoria_de_licencia": "SIN LICENCIA", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "ATROPELO A PEATON", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PUBLICO", "_60_adel_3_edad_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "WILLIAM VASQUEZ  PONCE", "tipo_de_vehiculo_protagonista": "VAGONETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL MANUEL ASCENCIO VILLARROEL", "todos_los_nombres_de_los_afectados_": "PERSONA HERIDA: FAUSTINA SILVESTRE CRUZ", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO PUNATA", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. IMNOMINADA  ALTURA INGRESO A LA NORMAL DE PARACAYA ZONA PARACAYA", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "NINGUNO", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "MY. FANOR SANDOR GUIZADA HERBAS CEL: 