or LEYLA SOTO ARIAS de tres años se encuentra hospitalizada.\r\nSe a realizado el levantamiento legal de cadaer y su traslado a la Morgue del IDIF.\r\nSe realizo la toma de muestra para el examen de alcoolemia.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "-17.391043, -66.250827", "categoria_de_licencia": "´´B´´", "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "ATROPELLO A CICLISTA", "0_a_12_niosas_herido_mujer": 1, "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "31_a_45_mayores_muertos_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "WILMER RODRIGO MAMANI QUISPE", "tipo_de_vehiculo_protagonista": "VAGONETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "CLINICA SANTA RITA", "todos_los_nombres_de_los_afectados_": "PERSONA FALLECIDA: PAOLA ARIAS FLORES DE32 AÑOSPERSONA HERIDA: LEYLA SOTO ARIAS DE 3 AÑOS", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 2, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. BLANCO GALINDO ENTRE AV. ELIAS MENECES KM 10", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "NINGUNO", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "CAP. JAIME VILLCA CALANI CEL. 68838623", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "APREHENDIDO", "sancion_trabajo_comunitario_papeleta_valorada_sancion_pecuniaria_proceso_de_investigacion": "PROCESO DE INVESTIGACION"}', '2026-02-11 05:26:40.890784', '2026-02-11 05:26:40.890784');
