e que fue agredido físicamente por parte de los familiares de la víctima, posteriormente personal policial dependiente de la Unidad de Bomberos de la Policia Boliviana evacuan a la persona herida para su pronta atención, acto seguido personal de la división accidentes de la jefatura de Epi Sur se constituye a la Clinica San Miguel, donde se llega  tomar contacto con la Sra. Wilma Zerda Sanchez de Mamani  quien refiere que es encontraba conduciendo su motocicleta, cuando fue sorprendida y llega a ser envestida por un vehiculo a consecuencia del accidente resulta herida, posteriormente llegue  a tomar contacto con el Dr. Angel Cordova medico de turno quien diagnostica a la Sra. Wilma Zerda Sanchez de Mamani  \r\n•\tPolicontusa", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.462562, -66.201700", "categoria_de_licencia": "\"C\"", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "CALLE", "sub_clasificacion_hechos": "COLISION LATERAL", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "18_a_30_mayores_herido_mujer": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "JESUS RAMIRO TORREZ GABRIEL", "tipo_de_vehiculo_protagonista": "AUTOMOVIL", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "BUENO", "nombres_de_los_nosocomio_auxiliados": "HOSPITAL DEL SUD", "todos_los_nombres_de_los_afectados_": "WILLMA ZERDA SANCHEZ DE MAMANI", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO EPI SUR", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "INGRESO A PRIMERO DE MAYO", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES D