Clínica Santa Rita con un diagnóstico de Policontusion, trauma torácico, fractura de clavícula derecha distal, esguince de rodilla derecha lateral, esguince de tobillo derecho. \r\nSeguidamente la motocicleta fue trasladada  a dependencia de tránsito así también se procedió a la extracción de la Muestra Sanguínea del conductor de la motocicleta protagonista el presente caso se encuentra en proceso de investigación y pasa a conocimiento del ministerio público.", "clasificacion_hecho": "ATROPELLO", "gps_latitud_longitud": "-17.395468,-66.303437", "categoria_de_licencia": "´´M´´", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "AVENIDA", "sub_clasificacion_hechos": "ATROPELO A PEATON", "comunidad_localidad_ninguno": "NINGUNO", "tipo_de_servicio_que_presta": "PARTICULAR", "31_a_45_mayores_herido_varon": 1, "n_de_resolucion_de_la_sancion": "NINGUNO", "nombre_conductor_protagonista": "ABNER HUAYRAÑA ADOVIRI", "tipo_de_vehiculo_protagonista": "MOTOCICLETA", "division_accidentes_y_especiales": "ACCIDENTES", "temperancia_sobrio_sancionable_etc": "SOBRIO", "estado_de_la_via_bueno_malo_regular": "REGULAR", "nombres_de_los_nosocomio_auxiliados": "CLINICA SANTA RITA", "todos_los_nombres_de_los_afectados_": "PERSONA HERIDA: ALEUTERIO CHOQUE CHIPATA", "categorizacion_de_carreteras_ninguno": "NINGUNO", "tramo_carretero_salidallegadaninguno": "NINGUNO", "tipo_de_denuncia_escrito_verbal_oficio": "OFICIO", "total_clasificacion_de_los_damnificados": 1, "unidad_de_transito_que_registra_el_caso": "TRANSITO QUILLACOLLO", "avenidacalle_del_hecho_calle_av_alt_y_carretera": "AV. ALBINA PATIÑO INMEDIACIONES MUÑECO FERRARI", "empresa_sindicato_o_institucion_al_que_pertenece": "NINGUNO", "otros_datos_vehiculos_y_conductores_damnificadas": "DAÑOS MATERIALES", "grado_nombre_apellido_y_n_de_celular_del_investigador_asigando": "TTE: ALEX HUGO LOZANO MORA CEL: 68838623", "situacion_jurica_del_sindicado_arrestado_aprehendido_se_dio_a_la_fuga_no": "NO", "sancion_trabajo_comunitario_papeleta_v