INSERT INTO public.incidentes (id, fecha_hora_hecho, latitud, longitud, usuario_id, unidad_policial, tipo_formulario, codigo_caso_principal, datos_especificos, created_at, updated_at) VALUES (138, '2025-08-31 11:00:00', -17.03506300, -64.87065700, NULL, 'TRANSITO IVIRGARZAMA', 'transito_03a', '042/2025', '{"edad": "SE DIO A LA FUGA", "sexo": "SE DIO A LA FUGA", "placa": "SE DIO A LA FUGA", "causas": "POR CAUSAS QUE SE INVESTIGA", "n_caso": "042/2025", "gestion": 2025, "form03a_": 110, "provincia": "CHAPARE", "cod_filtro": 1, "hora_hecho": "1899-12-30T11:32:36.000Z", "municipios": "PUERTO VILLARROEL", "soat_si_no": "SE DIO A LA FUGA", "zona_hecho": "ESTE", "fecha_hecho": "2025-08-31T04:00:36.000Z", "departamento": "COCHABAMBA", "mes_registro": "AGOSTO", "nacionalidad": "BOLIVIANO", "total_heridos": 1, "total_muertos": 1, "estado_del_caso": "CASO EN INVESTIGACION", "grado_alcoholico": "SE DIO A LA FUGA", "muertos_pasajeros": 1, "remision_del_caso": "MINISTERIO PUBLICO/FISCALIA", "medidas_cautelares": "NINGUNO", "numero_de_licencia": "SE DIO A LA FUGA", "area_rural_o_urbano": "RURAL", "breve_detalle_hecho": "BREVE DETALLE HECHO:     El día domingo 31, de agosto de 2025, a horas 13:00 p.m. aprox. Ah llamado de la Sra. Zulma Pereira nos constituimos al hospital central de Ivirgarzama donde se tomó contacto con el medico de turno que el mismo refiere que aprox. A las 07:00 am ingresaron a dicho nosocomio 2 personas heridos por hecho de transito, suscitado en la carretera Cbba a Santa Cruz altura población de Paraíso del Municipio de Puerto Villarroel hecho de transito, técnicamente denominado COLISION CON PERSONA HERIDO Y FALLECIDO, protagonizada por el vehículo Clase vagoneta sin mayores referencias conducido por el Sr. NN (persona no identificado), quien se encontraba circulando por la carretera Cbba a Santa Cruz, por causas que se investiga, llega a colisionar  al vehículo tipo motocicleta sin mayores detalles de servicio particular conducido por el Menor. Bismark Soria Montaño de 16 años de edad quien de igual manera  circulaba por la carretera Cbba a Santa Cruz en sentido de orientación de Oeste a este (Chimore a Ivirgarzama) el vehículo tipo vagoneta después de colisionar se da a la FUGA  con rumbo desconocido sin prestar auxilio a las víctimas donde es seguido por los familiares de las victimas a consecuencia de este hecho de transito resulto herido el menor BISMARK SORIA MONTAÑO de 16 años de edad (conductor de la motocicleta) y el Sr. Alberto Teran Quispe de 48 años aprox. (acompañante de la motocicleta) donde ambos fueron auxiliados por un vehiculo particular al hospital central de Ivirgarzama, el menor Bismark Soria Montaño con diagnóstico medico TEC LEVE y POLICONTUCIONES y el Sr. Alberto Teran Quispe con diagnostico medico TEC GRAVE, FRACTURA DE BASE DE GRANEO FRACTURA EXPUESTA DE TIBIA PERONE IZQUIERDO Y TRAUMA INTESTINAL donde fallece cuando este era atendido por el personal médico de turno ambos valorados por el medico Dra. Llanque.\r\nPosteriormente familiares del Sr. Alberto Teran Quispe (+) ingresan al hospital central de Ivirgarzama sección emergencias familiares haciendo uso de la fuerza retiran al occiso Alberto Teran Quispe, a la hora se desconoce el Paradero del conductor Protagonista y del Occiso así mismo no se tiene conocimiento de los vehículos protagonistas.  \r\nNo se secuestraron los vehículos protagonistas del hecho de tránsito.\r\nEl presente caso las causas y circunstancias se encuentran en proceso de investigación y pasa a conocimiento del Ministerio Público.", "clasificacion_hecho": "COLISION", "gps_latitud_longitud": "-17.035063, -64.870657", "categoria_de_licencia": "SE DIO A LA FUGA", "heridos_motociclistas": 1, "clasificacion_de_la_via_": "CARRETERA", "sub_clasificacion_hechos": "COLISION POR ALCANCE", "comunidad_localidad_ninguno": "PARAISO", "tipo_de_servicio_que_presta": "SE DIO A LA FUGA", "13_a_17_menores_herido_varon": 1, "46_a_59_mayores_muertos_varon": 1, "n_de_resolucion_de_la_sancion